  "test": "import pytest

from langfuse import observe


def test_async_observe_uses_fully_qualified_default_name(langfuse_memory_client, memory_exporter):
    @observe()
    async def async_func() -> int:
        return 123

    # Run the coroutine
    result = pytest.run(async_func()) if hasattr(pytest, 'run') else None
    # If pytest.run is not available, just use asyncio
    import asyncio
    result = asyncio.get_event_loop().run_until_complete(async_func())
    assert result == 123

    langfuse_memory_client.flush()
    spans = memory_exporter.get_finished_spans()
    expected_name = f"{async_func.__module__}.async_func"
    assert any(span.name == expected_name for span in spans)


def test_sync_observe_uses_fully_qualified_default_name(langfuse_memory_client, memory_exporter):
    @observe()
    def sync_func() -> str:
        return "ok"

    assert sync_func() == "ok"

    langfuse_memory_client.flush()
    spans = memory_exporter.get_finished_spans()
    expected_name = f"{sync_func.__module__}.sync_func"
    assert any(span.name == expected_name for span in spans)
